public static MoleculeSpec sodiumIon() {
    return AvogadroApi.builder("guide:sodium_ion")
        .name("Sodium ion")
        .atom("Na", 0, 0, 0)
        .noBonds()
        .atomConfiguration(0, 11, 12, 1, 2, 8)
        .build();
}

