public static MoleculeSpec waterAndEthanol() {
    // Component references add inspection links, not geometry.
    return AvogadroApi.builder("guide:water_ethanol_pair")
        .name("Water and ethanol")
        .smiles("[H]O[H].CCO")
        .component("guide:water")
        .component("guide:ethanol")
        .classification(MoleculeClassification.MIXTURE)
        .inspectionMetadata("note",
            "One molecule of each; an illustrative pair, not a bulk concentration.")
        .build();
}

